// om — Afaan Oromoo (oromo).
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// ---------------------------------------------------------------------------------------------------
// ESTE É O DICIONÁRIO DE MENOR CONFIANÇA DO SYDEN. O oromo tem pouca presença nos textos de que eu
// aprendi, e ninguém da dupla o lê. As frases estão compreensíveis, mas pedem revisão de quem fala
// a língua antes de alguém confiar nelas — e, se essa revisão vier, ela vale mais que este arquivo.
// ---------------------------------------------------------------------------------------------------
//
// TRATAMENTO: **ati** (singular), e não *isin* (o plural, que também é o de respeito). É o que o
// CLAUDE.md manda. Os botões vão no imperativo singular (Ergi, Olkaa’i, Haqi), que é o das
// interfaces em oromo.
//
// ONDE O OROMO ESCONDE O GÊNERO: NA TERCEIRA PESSOA, e não em quem lê. "Ati" e o verbo dele são os
// mesmos para homem e mulher — o hauçá e o amárico, que vieram antes, não tinham essa sorte. O sexo
// aparece em "inni" (ele) e "isheen" (ela), e o verbo acompanha: inni dhufe / isheen dhufte. Então
// toda frase que fala de OUTRA pessoa, de sexo que o Syden não sabe, vai pela passiva ou pelo
// impessoal: "Akkaawuntiin kun haqameera" (esta conta foi apagada), e não "ele/ela apagou a conta".
//
// O APÓSTROFO É LETRA: a hudhaa (’) marca a parada glotal dentro da palavra — olkaa’i, ba’e,
// qindaa’ina. Vai como ’ (U+2019), e não como o ' reto, que exigiria escapar dentro das aspas do
// arquivo — e escapar já sumiu com pares inteiros calado (ver a armadilha do hauçá).
//
// LETRAS DOBRADAS SÃO OUTRA PALAVRA: vogal longa (aa, ee) e consoante dobrada mudam o sentido, como
// acento muda em português. Por isso nada aqui foi "simplificado".
//
// NÚMEROS: o substantivo depois do número não muda (ergaa 1, ergaa 5), então o {n} vai direto, sem
// o truque do rótulo que o polonês e o ucraniano precisaram. `Intl.NumberFormat('om')` não existe
// no Chrome (ver web/src/algarismos.ts): ele cai na separação neutra, com 0-9.
//
// VOCABULÁRIO, decidido uma vez: comunidade = hawaasa, canal = chaanaalii, sala de voz = kutaa
// sagalee, chamada = waamicha, conversa = haasaa, mensagem = ergaa, senha = jecha icciitii, lixeira =
// kuusaa haqamee, tópico = mata duree, conta = akkaawuntii, administrador = bulchaa, dono = qabeessa,
// cargo = gahee, convite = affeerraa, perfil = piroofaayilii, transmissão = tamsaasa, configurações =
// qindaa’ina, amigos = hiriyoota, tela = iskiriinii, vila = ganda, coelho = illeenteessa.
//
// SELO E INSÍGNIA SEPARADOS: selo = chaappaa (o da comunidade), insígnia = mallattoo (a da pessoa).

