    'Yeroo waamichaa, qabduun kun sagalee kana nama kutaa keessa jiru hundaaf taphachiisa. Kuusaalee qophaa’an fe’i ykn kan kee olkaa’i; kan ati jaallattu fuuldura gabatee irra jira.',
  'É a primeira coisa que alguém vê ao entrar na comunidade, uma vez só. Sem isto, a pessoa cai direto na lista de canais.':
    'Kun waan namni hawaasa seenu jalqaba argu, yeroo tokko qofa. Kana malee, kallattiin tarree chaanaalii irra ga’a.',
  'É assim que os outros veem você na lista e nas conversas.': 'Namoonni biroo tarree fi haasaa keessatti akkasitti si argu.',
  'é o que você está enviando': 'wanta ati ergaa jirtu',
  'É o seu único jeito de entrar. Defina uma senha antes de desligar.': 'Kun karaa kee isa tokkicha seenuuti. Osoo addaan hin kutin jecha icciitii kaa’i.',
  'E-mail': 'Imeelii',
  'Eco de lugar grande e vazio.': 'Sagalee deebii iddoo guddaa fi duwwaa.',
