  'Endereço guardado. Confira a sua caixa de entrada para confirmar.': 'Teessoon kuufameera. Mirkaneessuuf saanduqa galmee kee ilaali.',
  'Endereço guardado. O envio de e-mail ainda não está ligado neste servidor, então o link de confirmação ficou no registro do servidor.':
    'Teessoon kuufameera. Imeelii erguun sarvarii kana irratti ammallee hin banamne, kanaaf liinkiin mirkaneessaa galmee sarvarii keessa jira.',
