  'Os números aparecem no alto da lista de canais, para todo mundo, e mudam sozinhos.': 'Lakkoofsonni gubbaa tarree chaanaalotaa irratti nama hundaaf ni mul’atu, ofumaanis ni jijjiiramu.',
  'Criar uma sala para cada pessoa que entrar': 'Nama seenu hundaaf kutaa uumi',
