  'Estrelas necessárias': 'Urjiiwwan barbaachisan',
  'Quando uma mensagem junta estrelas ⭐ suficientes, o Syden a publica no canal de destaques. A estrela de quem escreveu não conta, e apagar a mensagem apaga o destaque.': 'Ergaan tokko urjii ⭐ gahaa yoo argate, Syden chaanaala filatamoo keessatti maxxansa. Urjiin nama barreesse hin lakkaa’amu, ergaa haquun filatamaa sanas ni haqa.',
  '🎉 Resultado do sorteio de {premio}: {vencedores}. Parabéns!': '🎉 Bu’aa carraa {premio}: {vencedores}. Baga gammaddan!',
  '🎉 Sorteio: {premio}! Reaja com 🎉 para participar. O resultado sai em {quando}.': '🎉 Carraa: {premio}! Hirmaachuuf 🎉 tuqaa. Bu’aan {quando} ba’a.',
  'Começar o sorteio': 'Carraa jalqabi',
