  'O sorteio de {premio} terminou sem participantes.': 'Carraan {premio} hirmaattota malee xumurame.',
  'O Syden anuncia o prêmio no canal, e quem quiser participar reage com 🎉. Na hora marcada, ele sorteia entre quem reagiu e publica o resultado.': 'Syden badhaasa chaanaala keessatti beeksisa, namni hirmaachuu barbaadu 🎉 tuqa. Yeroo murtaa’etti warra tuqan keessaa carraa baasee bu’aa maxxansa.',
