  'Aniversário': 'Guyyaa dhalootaa',
  'Aniversários': 'Guyyoota dhalootaa',
  'Canal dos parabéns': 'Chaanaala baga gammaddan',
  'Dia': 'Guyyaa',
  'Hoje é aniversário de {pessoa}! 🎉 Parabéns!': 'Har’a guyyaa dhaloota {pessoa} ti! 🎉 Baga dhalatte!',
  'Mês': 'Ji’a',
  'No dia do aniversário de quem informou a data, o Syden publica os parabéns no canal escolhido. Use {pessoa} no lugar do nome.': 'Guyyaa dhaloota nama guyyaa isaa galchee, Syden chaanaala filatame keessatti baga gammaddan maxxansa. Bakka maqaa {pessoa} fayyadamaa.',
  'Só o dia e o mês, nunca o ano. As comunidades que avisam aniversários dão os parabéns no dia. É opcional, e dá para apagar quando quiser.': 'Guyyaa fi ji’a qofa, waggaa gonkumaa miti. Hawaasni guyyoota dhalootaa beeksisu guyyaa sana baga gammaddan jedha. Filannoo dha, yeroo barbaaddan haquu ni dandeessu.',
  'Texto dos parabéns': 'Barreeffama baga gammaddanii',
  'Agendar': 'Sagantaa baasi',
  'Apagar a mensagem agendada': 'Ergaa sagantaan qophaa’e haqi',
