  'Na hora marcada, o Syden publica o texto no canal. Dá para repetir todo dia ou toda semana.': 'Yeroo murtaa’etti Syden barreeffama chaanaala keessatti maxxansa. Guyyaa guyyaan yookaan torban torbaniin irra deebi’uu danda’a.',
