  'Uma vez': 'Al tokko',
  'Alguém escreve o comando no começo de uma mensagem, como !regras, e o Syden responde no canal com o texto que você cadastrar. Use {pessoa} para o nome de quem pediu e {comunidade} para o nome da comunidade.': 'Namni tokko jalqaba ergaa irratti ajaja akka !regras barreessa, Syden immoo barreeffama isin galchitaniin chaanaala keessatti deebisa. Maqaa nama gaafateef {pessoa}, maqaa hawaasaatiif {comunidade} fayyadamaa.',
