  'Quanto tempo cada pessoa espera entre uma mensagem e outra no canal.': 'Namni hundi chaanaala keessatti ergaa gidduu hammam akka eegu.',
  'Regras': 'Seerota',
  'Regras que o Syden aplica sozinho, antes de a mensagem aparecer. Quem administra não passa por elas. A mensagem barrada volta para quem escreveu, com o motivo, e ninguém mais a vê.': 'Seerota Syden mataa isaatiin ergaan osoo hin mul’atin hojiirra oolchu. Bulchitoota hin ilaallatan. Ergaan cufame sababa isaa wajjin nama barreesseetti deebi’a, namni biraa hin argu.',
  'Salvo.': 'Kuufameera.',
  'Uma por linha. Vale a palavra inteira, sem diferença de acento ou de maiúscula: proibir uma palavra não barra outra mais longa que só a contenha.': 'Sararaan tokko. Jechi guutuun lakkaa’ama, garaagarummaa mallattoo yookaan qubee gurguddaa malee: jecha tokko dhorkuun jecha dheeraa isa qofa of keessaa qabu hin cufu.',
  '{faltam} pontos para o nível {proximo}.': 'Sadarkaa {proximo}tti qabxii {faltam} hafe.',
  'Adicionar recompensa': 'Badhaasa dabali',
  'Cada mensagem vale pontos (uma por minuto), e cada minuto numa sala com mais alguém também. Quem sobe de nível recebe um aviso só para si.': 'Ergaan hundi qabxii qaba (daqiiqaatti tokko), daqiiqaan kutaa keessatti nama biraa waliin dabarsitan hundis akkasuma. Namni sadarkaa ol ba’u beeksisa ofuma isaaf qofa argata.',
  'Cargo da recompensa': 'Gahee badhaasaa',
  'Crie um cargo acima para usar como recompensa.': 'Akka badhaasaatti fayyadamuuf gahee olitti uumi.',
