  'Cargos dão nome e cor a grupos de pessoas: "Veterano", "Turma da raide". Não mudam o que cada um pode fazer na comunidade.': 'Gaheewwan garee namootaatiif maqaa fi halluu kennu: "Kan durii", "Garee haleellaa". Waan namni tokko hawaasa keessatti gochuu danda’u hin jijjiiran.',
