  'Cinza neutro, quase preto, com verde-água.': 'Daalachaa giddu-galeessaa, gurraacha dhihaatu, magariisa galaanaa waliin.',
  'Alto contraste': 'Garaagarummaa olaanaa',
  'Preto, branco e amarelo, para ler sem esforço.': 'Gurraacha, adii fi keelloo, salphaatti dubbisuuf.',
  'A paleta vale no tema escuro. Com o sol ligado, o Syden usa o tema claro.': 'Gurmuun halluu kun dhiheessa dukkanaa irratti hojjeta. Aduun yeroo banamtu Syden dhiheessa ifaa fayyadama.',
