  'Esta música não tem letra. Dá para subir de novo com um arquivo .lrc junto.': 'Weedduun kun jechoota hin qabu. Faayilii .lrc wajjin irra deebi’uun olkaa’uu dandeessa.',
  'Esta pessoa excluiu a conta. As mensagens daqui não chegam a ninguém.': 'Akkaawuntiin kun haqameera. Ergaan asii nama tokkoofuu hin ga’u.',
  'Esta transmissão está sem som. Quem transmite precisa marcar “compartilhar áudio” ao escolher a tela.':
    'Tamsaasni kun sagalee hin qabu. Namni tamsaasu yeroo iskiriinii filatu “sagalee qoodi” mallatteessuu qaba.',
