  'Nenhum pacote ainda. Monte o primeiro com imagens suas, ou publique os emojis que esta comunidade já tem.':
    'Ammallee kuusaan hin jiru. Kan jalqabaa suuraalee keetiin qopheessi, ykn emojii hawaasni kun qabu maxxansi.',
