  'O selo aparece aqui quando o primeiro marco cair. Até lá ele fica guardado — e chegar nele é justamente o que ele vai significar.':
    'Chaappaan yeroo galmi jalqabaa ga’amu asitti mul’ata. Hamma sanaatti kuufamee tura — achi ga’uun immoo wanta inni hiikuudha.',
  'O selo desta comunidade é': 'Chaappaan hawaasa kanaa:',
  'O servidor demorou demais para responder. Tente de novo.': 'Sarvarichi deebisuuf baay’ee tura. Irra deebi’ii yaali.',
  'O som chega quando você abre esta transmissão.': 'Sagaleen yeroo ati tamsaasa kana bantu dhufa.',
  'O survival do Léo': 'Sarvarii jiraachuu kan Lammii',
  'O Syden já sabe escrever em qualquer uma destas línguas — falta a tradução dos textos. Enquanto ela não chega, o que não estiver traduzido aparece em português, e as letras de cada alfabeto aparecem certas, sem quadradinhos.':
    'Syden afaanota kana keessaa kamiinuu barreessuu danda’a — kan hafe hiikkaa barreeffamaati. Hamma inni dhufutti, wanti hin hiikamne Afaan Poorchugaaliitiin mul’ata, qubeen qubee hundaa sirriitti, saanduqa xixiqqaa malee mul’atu.',
  'O Syden vai ficar fora do ar por uns 10 minutos para uma atualização.': 'Syden fooyya’iinsaaf daqiiqaa 10 dhiyaatuuf hin argamu.',
