  'Seu microfone está bloqueado: ninguém está te ouvindo.': 'Maaykiroofoonni kee cufameera: namni si dhagahu hin jiru.',
  'Quem bloqueia é o Windows. Abra Configurações do Windows → Privacidade e segurança → Microfone e ligue o acesso para o navegador.': 'Kan cufe Windows dha. Qindaa’ina Windows → Dhuunfaa fi nageenya → Maaykiroofoonii bani, eeyyama brawuzeriif banii.',
  'Clique no ícone à esquerda do endereço do site, ative o Microfone, e o Syden liga sozinho.': 'Mallattoo teessoo marsariitii bitaa jiru cuqaasi, Maaykiroofoonii banii, Syden ofumaan ni banata.',
  'Seu microfone não está mandando som: ninguém está te ouvindo. Clique para escolher outro.': 'Maaykiroofoonni kee sagalee hin ergu: namni si dhagahu hin jiru. Kan biraa filachuuf cuqaasi.',
