  'Já tem uma partida acontecendo nesta sala.': 'Kutaa kana keessatti taphni duraanuu adeemaa jira.',
  'Só quem começou a partida pode encerrá-la antes do fim.': 'Kan taphicha jalqabe qofatu osoo hin xumuramin dura dhaabuu danda’a.',
  'Lobisomem': 'Nama-jeedala',
  'À noite, escolha com os outros lobisomens quem atacar. De dia, não deixe ninguém desconfiar.': 'Halkan, nama-jeedalawwan kaan waliin eenyuun akka haleelan filadhu. Guyyaa, namni tokkollee akka si shakku hin eeyyamin.',
  'Vidente': 'Raajii',
  'À noite, descubra se alguém é lobisomem. Conte de dia, se achar que vale o risco.': 'Halkan, nama tokko nama-jeedala ta\'uu fi dhiisuu qori. Yoo balaa irra galuun ni barbaachisa jette guyyaa himi.',
  'Anjo': 'Ergamaa Waaqaa',
  'À noite, escolha alguém para proteger. Se os lobisomens atacarem essa pessoa, ela sobrevive.': 'Halkan, nama tokko eeguuf filadhu. Yoo nama-jeedalawwan nama sana haleelan, ni hafa.',
  'Da vila': 'Nama ganda',
  'À noite, durma. De dia, descubra quem são os lobisomens e vote para tirá-los do jogo.': 'Halkan rafi. Guyyaa, nama-jeedalawwan eenyu akka ta\'an barbaadi, taphicha keessaa akka ba\'aniif sagalee kenni.',
  'A vila venceu!': 'Gandi mo\'e!',
  'Os lobisomens venceram!': 'Nama-jeedalawwan mo\'an!',
  'Noite {n}. A vila dorme.': 'Halkan {n}. Gandi rafeera.',
  'Os lobisomens atacaram {nome} durante a noite.': 'Nama-jeedalawwan halkan {nome} haleelan.',
  'Ninguém morreu esta noite.': 'Halkan kana namni du\'e hin jiru.',
  'Dia {n}. Conversem e votem em quem vocês acham que é lobisomem.': 'Guyyaa {n}. Mari\'adhaa, nama nama-jeedala jettanii yaaddaniif sagalee kennaa.',
  'A vila tirou {nome} do jogo.': 'Gandi {nome} taphicha keessaa baase.',
  'Empate: ninguém sai hoje.': 'Walqixa: har\'a namni ba\'u hin jiru.',
  'Clique em quem os lobisomens vão atacar.': 'Nama nama-jeedalawwan haleelan irratti cuqaasi.',
  'Você já usou a sua visão esta noite.': 'Halkan kana mul\'ata kee itti fayyadamteetta.',
  'Clique em alguém para descobrir se é lobisomem.': 'Nama-jeedala ta\'uu fi dhiisuu beekuuf nama tokko irratti cuqaasi.',
  'Clique em quem você quer proteger esta noite.': 'Nama halkan kana eeguu barbaaddu irratti cuqaasi.',
  'Durma. Os outros papéis estão agindo.': 'Rafi. Gaheewwan kaan hojjechaa jiru.',
  'Você saiu do jogo. Agora só assiste — sem contar nada!': 'Taphicha keessaa baateetta. Amma ilaaluu qofa — homaa hin himin!',
  'Clique em quem você quer tirar do jogo. O mais votado sai; empate, ninguém.': 'Nama taphicha keessaa baasuu barbaaddu irratti cuqaasi. Kan sagalee baay\'ee argate ni ba\'a; walqixa yoo ta\'e, namni hin ba\'u.',
  'é lobisomem': 'nama-jeedala',
  'não é lobisomem': 'nama-jeedala miti',
