  'A solução do problema.': 'Furmaata rakkoo kanaa.',
  'Acertou! Agora é torcer pelos outros.': 'Sirrii! Amma warra kaan jajjabeessi.',
  'Esse não era o lance. Espere a solução.': 'Tarkaanfiin sun miti. Furmaata eegi.',
  'Você joga com as brancas. Ache o melhor lance.': 'Adiidhaan taphatta. Tarkaanfii hunda caalu barbaadi.',
  'Você joga com as pretas. Ache o melhor lance.': 'Gurraachaan taphatta. Tarkaanfii hunda caalu barbaadi.',
  'Ver este problema no Lichess': 'Rakkoo kana Lichess irratti ilaali',
  'Problema do Lichess · nota {nota}': 'Rakkoo Lichess · sadarkaa {nota}',
  'Cada um recebe um papel em segredo. À noite os lobisomens atacam; de dia a vila conversa e vota em quem tirar do jogo. Precisa de 4 pessoas ou mais.': 'Namni hundi icciitiin gahee argata. Halkan nama-jeedalawwan haleelu; guyyaa gandi mari\'atee eenyu taphicha keessaa akka ba\'u sagalee kenna. Namoota 4 ykn isaa ol barbaachisa.',
  'Problemas de xadrez': 'Rakkoolee saantaraajii',
  'Todo mundo recebe o mesmo problema do Lichess. Quem achar o lance certo mais rápido ganha o ponto extra.': 'Namni hundi rakkoo Lichess tokkuma argata. Kan tarkaanfii sirrii saffisaan argate qabxii dabalataa argata.',
  'Os problemas de xadrez não estão no servidor.': 'Rakkooleen saantaraajii sarvara irra hin jiran.',
  'Este problema já acabou.': 'Rakkoon kun xumurameera.',
  'Lance inválido.': 'Tarkaanfii hin hayyamamne.',
  'Solo': 'Kophaa',
  'Coletivo': 'Walii wajjin',
  'Palavra secreta': 'Jecha dhoksaa',
  'Todo mundo tenta adivinhar a mesma palavra de 5 letras, em 6 chutes. A sala vê as cores dos outros, mas não as letras. Quem acertar com menos chutes ganha mais pontos.': 'Namni hundi jecha qubee 5 qabu tokkuma yaalii 6 keessatti tilmaamuuf yaala. Halluu warra kaanii ni argita, qubee isaanii garuu hin argitu. Kan yaalii xiqqaan argate qabxii baay\'ee argata.',
  'A palavra era: {palavra}': 'Jechi: {palavra}',
  'Acabaram os seus chutes. Espere a palavra.': 'Yaaliin kee dhumeera. Jecha eegi.',
  'Escreva uma palavra de 5 letras e aperte Enter.': 'Jecha qubee 5 qabu barreessiitii Enter tuqi.',
  'Seu quadro': 'Gabatee kee',
  'Escreva uma palavra de 5 letras.': 'Jecha qubee 5 qabu barreessi.',
  'Essa palavra não está na lista.': 'Jechi kun tarree keessa hin jiru.',
