  'Crie os cargos da comunidade primeiro, em Membros. Depois volte aqui para entregá-los sozinhos.': 'Dura gaheewwan hawaasaa Miseensota keessatti uumi. Achii booda akka isaan ofumaan kennamaniif as deebi\'i.',
