  'O Syden publica uma mensagem no canal com um emoji para cada cargo. Quem reage ganha o cargo; quem tira a reação, perde.': 'Syden chaanaala keessatti ergaa gahee hundaaf emojii tokko qabu maxxansa. Kan deebii kenne gahee argata; kan deebii haqe gahee sana dhaba.',
