  '{tipo} «{item}» ({onde}) saiu do Syden porque {quem} disse ter os direitos. Se você tinha autorização para publicar, responda aqui contando: a sua resposta vai ser levada em conta. Enquanto isso não ficar claro, fica fora. Os termos explicam como funciona, na seção 4: https://syden.chat/termos.html#direito-autoral': '{tipo} «{item}» ({onde}) Syden irraa haqameera, sababni isaas {quem} mirga qabaachuu himeera. Yoo maxxansuuf hayyama qabaatte, asitti deebii kennii ibsi: deebiin kee ni ilaalama. Hanga kun ifa ta\'utti, haqamee tura. Akkaataa itti hojjetu haalawwan kutaa 4 keessatti ibsameera: https://syden.chat/termos.html#direito-autoral',
