  'Quem precisa falar com a administração abre um ticket no início da comunidade, com um assunto. Ele vira uma conversa privada em grupo entre essa pessoa e quem administra, e aparece na lista de conversas de vocês.': 'Namni bulchitoota waliin haasa\'uu barbaadu fuula jalqabaa hawaasaa irratti mata-duree waliin tikeetii bana. Tikeetiin sun haasaa garee dhuunfaa nama sanaa fi bulchitootaa gidduu ta\'a, tarree haasaa keessan keessattis mul\'ata.',
