  'O seu recurso foi recebido em {quando}. Quem cuida do Syden vai ler e responder.': 'Ol’iyyannoon kee {quando} fudhatameera. Warri Syden kunuunsan dubbisanii deebii ni kennu.',
  'O seu responsável': 'Itti gaafatamaa kee',
  'O seu tempo de hoje acabou': 'Yeroon kee har’aa xumurameera',
  'O Syden é para quem tem 13 anos ou mais.': 'Syden namoota waggaa 13 fi isaa ol ta’aniif.',
  'O Syden é para quem tem 13 anos ou mais. Ninguém vê a sua data.': 'Syden namoota waggaa 13 fi isaa ol ta’aniif. Namni guyyaa kee argu hin jiru.',
  'O Syden passou a pedir a idade de todo mundo, para proteger quem tem menos de 18 anos (a lei do ECA Digital). Ninguém vê a sua data: só a faixa de idade é usada.': 'Syden amma umurii nama hundaa gaafata, warra waggaa 18 gadii eeguuf (seera ECA Digital). Namni guyyaa kee argu hin jiru: garee umurii qofatu itti fayyadama.',
  'Para quem foi comunicado e o protocolo (ex.: SaferNet 123)': 'Eenyutti akka beeksifame fi lakkoofsa dhimmaa (fkn: SaferNet 123)',
  'Por segurança, a prévia das transmissões fica fechada para menores de idade.': 'Nageenyaaf, duraa-ilaalchi tamsaasaa warra waggaa 18 gadiitiif cufameera.',
  'Por segurança, menores de idade conversam no particular só com amigos.': 'Nageenyaaf, warri waggaa 18 gadii dhuunfaan hiriyoota qofa waliin haasa’u.',
  'Qual é a sua data de nascimento?': 'Guyyaan dhaloota kee yoomi?',
  'Quem muda estas regras é o seu responsável.': 'Seerota kana kan jijjiiru itti gaafatamaa kee ti.',
  'Quem tem de 13 a 15 anos usa o Syden com a conta ligada à de um pai, mãe ou responsável. É a lei (ECA Digital), e é para a sua segurança.': 'Warri waggaa 13 hanga 15 Syden akkaawuntii kan abbaa, haadha ykn itti gaafatamaa waliin walqabateen fayyadamu. Seera (ECA Digital) dha, nageenya keetiifis.',
  'Quem tem menos de 18 anos usa o Syden com proteções a mais, e de 13 a 15 anos com a conta ligada à de um responsável (a lei do ECA Digital).': 'Warri waggaa 18 gadii Syden eegumsa dabalataan fayyadamu, warri waggaa 13 hanga 15 immoo akkaawuntii kan itti gaafatamaa waliin walqabateen (seera ECA Digital).',
