  'No quarto, o que troca o dia pela noite?': 'Kutaa keessatti, maaltu guyyaa gara halkaniitti jijjiira?',
  'O tapete': 'Afata',
  'A planta': 'Biqiltuu',
  'O que dá para fazer com os móveis do seu quarto?': 'Meeshaalee kutaa keetii maal gochuu dandeessa?',
  'Vender': 'Gurguruu',
  'Plantar': 'Dhaabuu',
  'Arrumar como quiser': 'Akka barbaadde qindeessuu',
  'Quiz relâmpago': 'Gaaffii Ariifachiisaa',
  'Escolha a resposta certa antes que o tempo acabe.': 'Osoo yeroon hin dhumin deebii sirrii filadhu.',
  'Balsa a dois': 'Bidiruu Nama Lamaa',
  'Cada um rema de um lado: a remada empurra a balsa para o outro. Juntos, ela vai para a frente. Peguem as cenouras!': 'Tokkoon tokkoon gama tokkoon qaccee luga: qaccee lugachuun bidiruu gara gama biraatti dhiiba. Waliin, gara fuulduraatti deema. Kaarotii walitti qabaa!',
  'Retrato do coelho': 'Fakkii Hilleensaa',
  'Pare cada faixa com o retrato no lugar, de cima para baixo.': 'Sarara tokkoon tokkoon yeroo fakkiin bakka isaa jiru dhaabi, gubbaa irraa gara gadiitti.',
  'Revezamento do riacho': 'Dabarsaa Lagaa',
  'Reme alternando ◀ e ▶ quando o remo estiver com você.': 'Yeroo qacceen harka kee jiru ◀ fi ▶ wal jijjiiraa qaccee lugadhu.',
  'Fuga do rio': 'Laga Jalaa Baqachuu',
  'Aperte sem parar para nadar. Quando vier um tronco, mergulhe!': 'Daakuuf osoo hin dhaabbatin tuqi. Yeroo jirmi dhufu, bishaan jala seeni!',
  'Roda da feira': 'Geengoo Gabaa',
  'Aperte para a roda frear. Ela sempre desliza um pouco antes de parar.': 'Geengoo dhaabuuf tuqi. Yeroo hunda osoo hin dhaabbatin dura xiqqoo mucucaata.',
  'Uma tacada só': 'Rukuttaa Tokko Qofa',
  'Prenda a mira, depois a força. Quem parar mais perto da toca ganha.': 'Kaayyoo dhaabi, achiis humna. Kan boollatti dhiyoo dhaabbate mo\'a.',
  'Tambor da turma': 'Dibbee Garee',
  'Ouça, repita a batida no mesmo ritmo e acrescente uma no fim.': 'Dhaggeeffadhu, rukuttaa saffisuma wal fakkaatuun irra deebi\'iitii dhuma irratti tokko itti dabali.',
  'Torta de cenoura': 'Paayii Kaarotii',
  'Coma a torta com a sua dupla, alternando ◀ e ▶. Quem acabar primeiro ganha!': 'Paayii hiriyaa kee wajjin, ◀ fi ▶ wal jijjiiraa nyaadhu. Kan duraan xumure mo\'a!',
  'Trinca da horta': 'Sadeessa Maasii',
  'Pare os três rolos na mesma figura. Cada trinca vale um ponto.': 'Geengoo sadan fakkii tokko irratti dhaabi. Sadeessi tokkoon tokkoon qabxii tokko.',
  'Vidas': 'Lubbuu',
  'Cenoura teleguiada': 'Kaarotii Qajeelfamu',
  'Pronta': 'Qophaa\'aa',
  'No ar': 'Qilleensa irra',
  'Frear': 'Fiinoo',
  'Caiu! Agora é torcer de longe.': 'Kufte! Amma fagoo irraa jajjabeessuu dha.',
  'Segure e solte: cenoura teleguiada': 'Qabadhuu gadhiisi: kaarotii qajeelfamu',
  'Dois acertos você aguenta; o terceiro derruba. Curva fechada perto da cerca protege por um instante.': 'Rukuttaa lama obsuu dandeessa; kan sadaffaan si kuffisa. Garagalchi cimaan dallaa bira yeroo xiqqoof si eega.',
  'Acertos: {n}': 'Rukuttaa: {n}',
  'Pilotar (para trás, freia e dá ré)': 'Oofi (duubatti: fiinoo fi duubatti deebi\'uu)',
  'O barco desliza: tire o pé antes da curva. As argolas laranja dão um empurrão.': 'Bidiruun ni mucucaata: garagalchaa dura saffisa hir\'isi. Geengoon burtukaanaa dhiibbaa kennu.',
  'A toupeira-rei caiu!': 'Mootiin Moolee kufe!',
  'A turma caiu.': 'Gareen kufe.',
  'Dano da turma: {n}': 'Miidhaa garee: {n}',
  'Sem vidas: agora é torcer pela turma.': 'Lubbuun hin jiru: amma gareef jajjabeessuu dha.',
  'Fase {n} de {total}': 'Sadarkaa {n} kan {total}',
  'Torrão na mão!': 'Kuta biyyoo harka keessa!',
  'Bomba de semente pronta': 'Boombiin sanyii qophaa\'eera',
  'Atirar o torrão': 'Kuta biyyoo darbadhu',
  'Bomba de semente': 'Boombii sanyii',
  'Fuja das marcas no chão. Passe por cima de um torrão azulado para pegá-lo e atire de volta na toupeira; a bomba de semente é uma por fase.': 'Mallattoo lafa irra jiran jalaa baqadhu. Kuta biyyoo cuquliisa fakkaatu fudhachuuf irra darbiitii gara moolee deebisii darbadhu; boombiin sanyii sadarkaa tokkoof tokko qofa.',
  'Suba até o cata-vento. O que cai e os corvos levam de volta ao último andar.': 'Hanga agarsiisaa qilleensaatti ol ba\'i. Kufaatii fi qurarroon gara darbii dhumaatti si deebisu.',
  'Subir contra': 'Ol ba\'iinsa morkii',
  'Nenhum amigo subiu esta torre ainda.': 'Hiriyyaan masaraa kana ol ba\'e hin jiru ammaaf.',
  'Escolher a torre': 'Masaraa filadhu',
  'Esta subida já tinha começado quando você abriu: você assiste.': 'Ol bahiinsi kun yeroo ati banattu jalqabee ture: ilaalaa jirta.',
  'Suba o celeiro por tábuas, fardos e vigas que se mexem até o cata-vento lá no alto, desviando das ferramentas que caem e dos corvos. No Solo, contra o relógio e os fantasmas dos amigos.': 'Gootaraa gabatee, hidhaa citaa fi muka sochoo\'u irra hanga agarsiisaa qilleensaa gubbaatti ol ba\'i, meeshaalee kufan fi qurarroo jalaa baqachaa. Kophaa: sa\'aatii fi ekeraa hiriyootaa wajjin.',
  'Coelhos em teco-tecos sobre a horta, atirando ervilhas e uma cenoura teleguiada de cada vez. Dois acertos dá para aguentar; o terceiro derruba. O último no ar ganha.': 'Hilleensota xiyyaarota xixiqqoo keessa jiran maasii gubbaatti, atara fi kaarotii qajeelfamu tokko yeroo tokkotti dhukaasu. Rukuttaa lama obsuun ni danda\'ama; kan sadaffaan kuffisa. Kan dhumaa qilleensa irratti hafe mo\'a.',
  'A turma inteira contra a toupeira-rei, que sai das tocas em três fases. Fuja das marcas no chão, pegue os torrões azulados e atire de volta. Ganha a turma, ou ninguém.': 'Gareen guutuun Mootii Moolee wajjin morkata, inni sadarkaa sadiin boolla keessaa ba\'a. Mallattoo lafa irraa baqadhu, kuta biyyoo cuquliisa fakkaatan fudhadhuutii deebisii darbadhu. Gareen mo\'a, yookaan namni hin mo\'u.',
  'Corrida de barquinhos no lago, no riacho e no mangue. A água desliza: tire o pé antes da curva, cuidado com a margem e aproveite a correnteza e as argolas. No Solo, contra o relógio e os fantasmas dos amigos.': 'Dorgommii bidiruu xixiqqoo haroo, laga fi bosona maangiroovii irratti. Bishaan ni mucucaata: garagalchaa dura saffisa hir\'isi, qarqara of eeggadhuu yaa\'aa fi geengoota itti fayyadami. Kophaa: sa\'aatii fi ekeraa hiriyootaa wajjin.',
  'Ver tudo': 'Hunda ilaali',
  'Celeiro': 'Gootaraa',
  'Paiol': 'Kuusaa Midhaanii',
  'Silo': 'Siloo',
  'Estoura-balão': 'Baaloonii Dhoosi',
