  'Pegue as caixas e estoure os balões dos outros. Quem fica sem balão sai.': 'Saanduqoota fuudhii baaloonii warra kaanii dhoosi. Namni baaloonii hin qabne ni ba\'a.',
  'Você venceu!': 'Injifannoo!',
