  '{n} voltas': 'Marsaa: {n}',
  'A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega.': 'Humni lubbuu fi turboo dha: qarqara rukutuun ni fixa, sararri diimaa-adiin deebisee guuta.',
  'A nave explodiu: a energia acabou.': 'Doonichi dhoohe: humni dhume.',
  'Posição: {posicao} de {total}': 'Sadarkaa: {posicao} / {total}',
  'Escolher a pista': 'Karaa filadhu',
  'Corrida de naves-cenoura numa pista suspensa, muito mais rápida que o kart. A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega, e sair da pista é cair. No Solo, contra o relógio e os fantasmas dos amigos.': 'Fiigicha dooniiwwan kaarotii karaa rarra\'aa irratti, kaartii caalaa baay\'ee ariifataa. Humni lubbuu fi turboo dha: qarqara rukutuun ni fixa, sararri diimaa-adiin deebisee guuta, karaa irraa ba\'uun immoo kufuu dha. Kophaa: sa\'aatii fi ekeraa hiriyootaa wajjin.',
  'Os karts numa arena fechada, cada um com três balões. Pegue as caixas e use os itens para estourar os balões dos outros: quem fica sem balão sai, e ganha quem sobrar.': 'Kaartiiwwan dirree cufame keessatti, tokkoon tokkoon isaanii baaloonii sadii qabu. Saanduqoota fuudhii meeshaalee fayyadamuun baaloonii warra kaanii dhoosi: namni baaloonii hin qabne ni ba\'a, kan dhuma irratti hafe ni injifata.',
  'Esquadrilha da toca': 'Garee xiyyaaraa boollaa',
  'Aviõezinhos de cenoura contra a praga da horta: desvie das sementes, pegue os reforços e derrube o espantalho mecânico no fim. A turma voa as mesmas ondas, e a esquadrilha soma os pontos.': 'Xiyyaarota kaarrotii xixiqqoo ilbiisota maasii irratti: sanyii irraa fagaadhu, gargaarsa fudhadhu, dhuma irratti immoo sodaachisaa simbirroo maashinii kuffisi. Gareen dambalii walfakkaatu barara, qabxiin garee ni ida\'ama.',
  'O espantalho caiu!': 'Sodaachisaan simbirroo kufe!',
  'A praga venceu desta vez.': 'Yeroo kana ilbiisonni mo\'atan.',
