  'A sua Maravilha ficou de pé por 2 minutos.': 'Dinqiin kee daqiiqaa 2 dhaabbate.',
  'A Maravilha do computador ficou de pé por 2 minutos.': 'Dinqiin kompiitaraa daqiiqaa 2 dhaabbate.',
