  'Seus navios': 'Doonii kee',
  'Escolha um navio e toque no mar. Arraste para mudar de lugar.': 'Doonii filadhuu galaana tuqi. Iddoo jijjiiruuf harkisi.',
  'Sortear a frota': 'Doonii akkasumaan',
  'Sua frota já está pronta.': 'Dooniin kee duraanuu qophaa\'eera.',
  'Ponha todos os navios antes.': 'Dura doonii hunda kaa\'i.',
  'Escolha um navio.': 'Doonii filadhu.',
  'O navio não cabe aí.': 'Dooniin achi hin galu.',
  'Os navios não podem encostar um no outro.': 'Dooniiwwan wal tuquu hin danda\'an.',
  'Minigolfe 3D': 'Minigoolfii 3D',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': 'Boolla saddeet 3D keessatti, gorba, masaraa fi wiirtuu qilleensaa wajjin, hundi yeroo tokkotti boolla tokkicha taphatu. Kallattii qabachuu fi humna kennuuf harkisii gadhiisi. Kan walumaagalatti rukuttaa xiqqaa qabu mo\'ata.',
  'Ver o buraco de cima': 'Boolla gubbaadhaa ilaali',
  'Fora da pista! Mais uma tacada.': 'Karaa ala! Rukuttaa tokko dabalataa.',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Kallattii qabachuuf gara cinaatti, humnaaf gara gadiitti harkisii gadhiisi. Kiiboordiin: xiyyaan kallattii agarsiisa, Space qabatame immoo humna kenna.',
  'Futebol dos coelhos': 'Kubbaa Miilaa Hilleensotaa',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'Kubbaa miilaa dirree xiqqaa, gubbaadhaa. Kubbaa geessuuf tuqi, cimsitee rukutuuf Space qabadhu, X\'n dabarsi. Kutaa keessatti gareen roobootiin guutama.',
  'Quantos por time?': 'Gareen tokko meeqa?',
  'Seu time venceu!': 'Gareen kee mo\'ate!',
  'Seu time perdeu.': 'Gareen kee mo\'ame.',
  'Passe': 'Dabarsi',
  'Chutar': 'Rukuti',
  'Chutar (segure para mais força)': 'Rukuti (humna dabalataaf qabadhu)',
  'Gol!': 'Goolii!',
  'Gol contra': 'Goolii ofii',
  'Partida inválida.': 'Taphni sirrii miti.',
  'Ninguém para jogar.': 'Namni taphatu hin jiru.',
  'Caça às pragas da horta': 'Adamsa ilbiisota maasii',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'Qurantoowwanii fi hawwaannisni maasii lolaa jiru. Osoo hin baqatin dura xiyyeeffadhuu cuqaasi: rasaasni lakkaa\'amaadha, dambaliin hundis saffisaan dhufa. Kan qabxii hunda caalu argate mo\'a.',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'Osoo ilbiisonni hin baqatin dura xiyyeeffadhuu cuqaasi. Dhukaasni hundi kaarotii tokko fixa.',
  'Munição: {n}': 'Rasaasa: {n}',
  'Pontos: {n}': 'Qabxii: {n}',
  'Nesta onda': 'Dambalii kana keessatti',
  'Acabou a munição desta onda.': 'Rasaasni dambalii kanaa dhumeera.',
  'Tiro inválido.': 'Dhukaasa sirrii hin taane.',
  'Tabuleiro da turma': 'Taphataa Gabatee Garee',
  'Sem fim': 'Dhuma hin qabne',
  '2 minutos': 'Daqiiqaa 2',
  'Sua pilha chegou ao topo.': 'Tuulli kee gubbaa ga\'eera.',
  'Uma jogada não valeu.': 'Tarkaanfiin tokko hin lakkaa\'amne.',
  'Subir a pilha': 'Tuuliicha ol kaasi',
  'Setas para mover, Espaço para trocar, X para subir a pilha.': 'Socho\'uuf furtuuwwan xiyyaa, jijjiiruuf Space, tuulii ol kaasuuf X.',
  'A horta está salva!': 'Iddoon biqiltuu baraarameera!',
