  'Campanha': 'Duula',
  'Sem vidas.': 'Lubbuun hin hafne.',
  'Você volta em {n}…': 'Sekondii {n} booda deebitee dhufta…',
  'Arrancada': 'Fiiga saffisaa',
  'Andar': 'Deemi',
  'Especial': 'Addaa',
  'Pular': 'Utaali',
  'Bater': 'Rukuti',
  'Neste buraco': 'Boolla kana irratti',
  'Total': 'Waliigala',
  'Tacadas: {n}': 'Rukuttaa: {n}',
  'Puxe a bola para trás e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Kubbaa duubatti harkisii gadhiisi. Kiiboordiin: xiyyaan kallattii agarsiisa, Space qabatame immoo humna kenna.',
  'Na água! Mais uma tacada.': 'Bishaan keessa! Rukuttaa tokko dabalataa.',
  'No buraco!': 'Boolla keessa!',
  'Acabaram as tacadas.': 'Rukuttaan dhumateera.',
  'Para a esquerda': 'Gara bitaa',
  'Para a direita': 'Gara mirgaa',
  'Setas para correr, Espaço para pular (segure para ir mais alto).': 'Fiiguuf furtuuwwan xiyyaa, utaaluuf Space (ol caalaa deemuuf qabadhu).',
  'Nenhum amigo jogou esta fase ainda.': 'Hiriyyaan tokkollee sadarkaa kana hin taphanne ammallee.',
  'Chuva na horta: todo mundo ganha {n} cenouras.': 'Rooba iddoo biqiltuu: namni hundi kaarotii {n} argata.',
  '{nome} achou {n} cenouras escondidas.': '{nome}: kaarotiin dhokatan {n} argaman.',
  '{nome} trocou de lugar com {outro}.': '{nome} fi {outro} bakka wal jijjiiran.',
  'Faltou gente: a partida acabou antes do fim, sem troféus.': 'Namni hin guutamne: taphichi osoo hin xumuramin dhumate, injifannoo malee.',
  'Saiu antes do fim': 'Dhuma dura ba\'e',
  'Jogar o dado': 'Tuqaa darbadhu',
  '{nome} comprou a cenoura dourada!': '{nome}: kaarotiin warqee bitame!',
  'Comprar a cenoura dourada por {preco} cenouras?': 'Kaarotii warqee kaarotii {preco}n bitattaa?',
  'Comprar': 'Bitadhu',
  '{nome} chegou à cenoura dourada.': '{nome}: kaarotii warqeetti ga\'iinsa.',
  'Quantas rodadas?': 'Marsaa meeqa?',
  'Os coelhos defendem a horta de raposas, corvos e um texugo. Andem juntos, batam em combo e cuidem uns dos outros: de 1 a 4 pessoas.': 'Hilleensonni iddoo biqiltuu sanyiiwwan, qurraasaa fi cooraa irraa ittisu. Waliin deemaa, kombootiin rukutaa fi walii yaadaa: nama 1 hanga 4.',
  'Pulo do coelho': 'Utaalcha Hilleensaa',
  'Uma corrida de plataforma: correr, pular e não cair. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, numa fase ou nas três.': 'Fiigicha waltajjii: fiigi, utaali, hin kufin. Kophaa, sa\'aatii fi hafuurota hiriyyootaa wajjin; garee wajjin, kallattiin, sadarkaa tokko irratti ykn sadeen hunda irratti.',
  'Troque dois legumes vizinhos para juntar três ou mais iguais. A pilha sobe sem parar: não deixe chegar ao topo. Com a turma, as cadeias e os combos mandam caixotes para os outros.': 'Midhaan biqiltuu ollaa lama jijjiiri sadii ykn isaa ol kan wal fakkaatan walitti qabachuuf. Tuulli osoo hin dhaabbatin ol ba\'a: gubbaa akka hin geenye godhi. Garee wajjin, sansalataa fi kombootiin warra kaaniif saanduqa ergu.',
  'Seis buracos de minigolfe, todos jogando o mesmo ao mesmo tempo. Puxe a bola para trás e solte para dar a tacada. Ganha quem somar menos tacadas.': 'Boolla minigoolfii jaha, hundi yeroo tokkotti isuma tokko taphatu. Rukutuuf kubbaa duubatti harkisii gadhiisi. Kan rukuttaa waliigalaa xiqqaa qabu mo\'ata.',
  'Cada um joga o dado na sua vez e anda pela horta. Junte cenouras para comprar a cenoura dourada, e depois de cada rodada a turma joga um microjogo. Ganha quem tiver mais cenouras douradas.': 'Tokkoon tokkoon nama yeroo isaatti tuqaa darbatee iddoo biqiltuu keessa deema. Kaarotii warqee bituuf kaarotii walitti qabadhu, marsaa hunda booda gareen tapha xiqqaa taphata. Kan kaarotii warqee hedduu qabu mo\'ata.',
  'Os pódios e as conquistas da turma': 'Waltajjii fi milkaa’ina garee',
  'Visitar o quarto': 'Kutaa daawwadhu',
  'Quem visita o seu quarto': 'Eenyutu kutaa kee daawwachuu danda’a',
  'Todo mundo': 'Nama hunda',
  'Seus amigos': 'Hiriyoota kee',
  'Só quem você convidar': 'Warra ati affeerte qofa',
  'Qualquer conta pode entrar e ver os troféus em destaque.': 'Herregni kamiyyuu seenee badhaasa filataman ilaaluu danda’a.',
  'Seus amigos podem entrar e ver os troféus em destaque.': 'Hiriyoonni kee seenanii badhaasa filataman ilaaluu danda’u.',
  'Nem os amigos entram, só quem você marcar aqui.': 'Hiriyoonni illee hin seenan, warra ati asitti mallatteessite qofa.',
  'Você ainda não tem amigos para convidar.': 'Ammallee hiriyyaa affeertu hin qabdu.',
