  'Até sobrar um': 'Hanga namni tokko hafutti',
  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.': 'Magaalota gurguddoo Biraazil keessa deemi, magaalota bitii warra isaan irra dhaabbatan irraa kiraa fudhadhu. Naannoo guutuu yoo qabaatte, gamoowwan ijaaruu dandeessa. Jijjiiri, caalbaasii irratti dorgomi, maallaqni akka sirraa hin dhumne eeggadhu.',
