  'O fundo não é de uma cor só, e ficou como veio.': 'Duubni halluu tokko miti, kanaafuu akkuma ture dhiifame.',
  'No app do Syden, o recorte funciona com qualquer fundo.': 'Appii Syden keessatti duuba kamiyyuu balleessuun ni danda\'ama.',
  'O recorte com o modelo falhou, e ficou o recorte simples.': 'Moodeliin balleessuun hin milkoofne, kanaafuu mala salphaatu fayyadame.',
  'Mandar figurinha': 'Istiikarii ergi',
  'Tirar figurinha': 'Istiikarii baasi',
  'Crie figurinhas com as suas imagens, ou salve as que receber numa conversa.': 'Suuraa keetiin istiikarii uumi, ykn kan haasaa keessatti argattu olkaa’i.',
  'Dominó': 'Dominoo',
  'Truco': 'Truco',
  'Damas': 'Daamaa',
  'Batalha naval': 'Waraana galaanaa',
  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'Dominoo beekamaa, nama 2 hanga 4 (yoo 4 ta\'an, lama lamaan). Dhagoota fiixee isaaniitiin walitti qabsiisi, kan dursee xumure qabxii harka warra kaanii fudhata.',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'Truco Biraazil, kaardii banamee fi manilha waliin, nama 2 ykn garee lama lamaa nama 4n. Truco gaafadhu, gara jaha, sagal fi kudha lamaatti ol kaasi, ykn baqadhu. Kan qabxii 12 gahe mo\'ata.',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'Daamaa Biraazil: nyaachuun dirqama, fuuldurattii fi duubatti, mootiin immoo sarara qaxxaamuraa guutuu deema. Kutaan ni ilaala.',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'Namni hundi doonii isaa dhoksee galaana isa kaanii irratti dhukaasa. Yoo rukutte, irra deebi\'ii dhukaasi. Kan dursee doonii hunda liqimsiise mo\'ata. Kutaan ni ilaala.',
