  Xadrez: 'Chess',
  'Uma partida de xadrez inteira, com todas as regras. Quem abre fica com as brancas. A sala assiste.': 'Taphataa chess guutuu, seerota hundaa waliin. Kan jalqabu adiidhaan taphata. Kutaan ilaala.',
  'Xeque!': 'Cheek!',
  Dama: 'Mootittii',
  Torre: 'Masaraa',
  Bispo: 'Bishooppii',
  'Cozinha da toca': 'Kushiinaa boolla',
  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': "Wantoota qophii saanduqota keessaa fudhadhu, sabbaqa irratti muri, osoo hin gubiin bilacha fi ooveenii keessatti bilcheessi, saanii irratti qindeessii foddaa irratti kenni. Hundi ajaja walfakkaataa argata: kan daqiiqaa 3 keessatti saanii baay'ee kenne ni mo'ata.",
  'Pegar ou largar': "Fuudhuu ykn kaa'uu",
  'Este jogo precisa de gráficos 3D, que não abriram neste aparelho.': 'Taphni kun fakkiiwwan 3D barbaada, kanneen meeshaa kana irratti hin banamne.',
  'Este prato não é o pedido.': 'Saaniin kun ajaja miti.',
  Kickflip: 'Kickflip',
  Grab: 'Grab',
  Manual: 'Manual',
  'Rolê do coelho': 'Deemsa hilleensaa',
  'Um minuto na pista de skate. Pule, gire, faça grind nos corrimãos e emende as manobras num combo: cada manobra a mais multiplica os pontos, mas cair perde o combo inteiro.': "Daqiiqaa tokko paarkii skate keessatti. Utaali, naannessi, haala irratti grind godhi tooftaalee combo keessatti walitti hidhi: tooftaan dabalataa hundi qabxii ni baay'isa, garuu kufuun combo guutuu dhabsiisa.",
  Pausar: 'Dhaabi',
  'Caiu!': 'Kufe!',
  'Melhor combo: {n}': 'Combo isa gaarii: {n}',
  'Trânsito da toca': 'Tiraafikii Boollaa',
  'Um minuto para soltar os carros do cruzamento sem deixar que batam. Fila cheia também custa pontos.': 'Daqiiqaa tokko konkolaattota qaxxaamura irraa osoo wal hin dhahin gadi lakkisuuf. Tarreen guutames qabxii nama dhabsiisa.',
  Liberar: 'Gadi lakkisi',
  'Carrinhos da toca': 'Konkolaataa Taphataa Boollaa',
  'Uma pista de carrinhos de brinquedo com quatro faixas: o carro segue a faixa sozinho, e você só acelera. Acelerou demais na curva, ele sai voando e perde tempo. No Solo, contra o relógio, os fantasmas dos amigos e robôs.': 'Daandii konkolaataa taphataa sarara afur qabu: konkolaataan sarara isaa ofii isaatiin hordofa, ati saffisa qofa dabalta. Golee irratti saffisa baay\'ee yoo dabalte, daandii irraa barrisee yeroo dhaba. Kophaa: sa\'aatii, hafuurota hiriyyootaa fi roobootii wajjin.',
  'Acelerar': 'Saffisa dabali',
  'Saiu da pista!': 'Daandii irraa ba\'e!',
  'Saídas da pista: {n}': 'Daandii irraa ba\'uu: {n}',
  'Segure para acelerar e solte antes da curva: quando o carro treme, ele está no limite.': 'Saffisa dabaluuf qabadhu, golee dura gadhiisi: yeroo konkolaataan raafamu, daangaa irra jira.',
