  'Colorido': 'Halluu qabeessa',
  // Saúde do servidor: ações da Hetzner e diagnóstico do host
  "Diagnóstico do host": "Qorannoo keessummeessaa",
  "Registros limitados de Docker, SSH, logind e kernel dos três boots mais recentes. Podem conter endereços IP.": "Galmeewwan daangeffaman Docker, SSH, logind fi kernel jalqabsiisa sadan dhiyoo irraa. Teessoo IP qabaachuu danda’u.",
  "Atualizar diagnóstico": "Qorannoo haaromsi",
  "Ainda não há snapshot. Ele será coletado na próxima abertura do cofre.": "Ammallee suuraan hin jiru. Yeroo kuusaan itti aanu banamu ni walitti qabama.",
  "Coletado em {data}": "{data} walitti qabame",
  "Medido pela {nome}": "{nome}n safarame",
  "Os mesmos números do painel do provedor. Inclui o disco, que o servidor não mede sozinho.": "Lakkoofsota daashboordii dhiyeessaa wajjin tokko. Diskii, kan sarvarichi ofiin hin safarre, ni dabalata.",
  "Ações no servidor": "Gochoota sarvarii irratti",
  "O histórico da Hetzner: ligar, desligar e reiniciar, pelo painel ou pela API. Uma queda sem ação aqui não foi comandada por esses caminhos.": "Seenaa Hetzner: daashboordii ykn API irraa banuu, cufuu fi irra deebi’anii jalqabsiisuu. Addaan cituun asitti gocha hin qabne karaa kanaan hin jalqabne.",
  "Nenhuma ação registrada.": "Gochi galmaa’e hin jiru.",
  "Ligar o servidor": "Sarvarii bani",
