  'Ganha quem chegar mais perto. Só pontos, sem dinheiro.': "Tilmaamni baay’ee dhihoo ta’e ni mo’ata. Qabxii qofa, maallaqa hin qabu.",
  'Lançar resposta': "Deebii galchi",
