  // O fundo da câmera (16/11/2026)
  'Fundo da câmera': "Duuba kaameraa",
  'Desfocado': "Dhokfisi",
  'Desfoca, apaga ou troca o que aparece atrás de você. A imagem da câmera não sai do computador para isso.': "Waan duuba kee jiru ni dhokfisa, ni haqa ykn ni jijjiira. Kanaaf suurri kaameraa kompiitara kee keessaa hin bahu.",
  // A transmissão personalizada (16/11/2026)
  'Nativa': "Kan jalqabaa",
  'Resolução': "Qulqullina",
  'Quadros por segundo': "Fireemii sekondii tokkotti",
  'Para quando a escolha automática errar: a resolução e os quadros ficam os que você escolher, do começo ao fim da transmissão.': "Yeroo filannoon ofumaan ta'u dogoggoru: qulqullinni fi fireemiin akkuma ati filatteetti, jalqaba hanga dhuma tamsaasaatti turu.",
  // O Syden Broadcast (16/11/2026)
  'Os efeitos de voz e de câmera feitos no seu computador, sem enviar nada a um servidor.': "Saffisa sagalee fi kaameraa kompiitara kee irratti hojjetaman, waan tokkollee gara sarvarii osoo hin ergin.",
  // A Masmorra da Toca (16/11/2026)
  'Masmorra da Toca': "Mana hidhaa boollaa",
  'Atravessem juntos a toca do rei-cogumelo: salas cheias de bichos, um baú com a cenoura que vai e volta, botões que pedem dois ao mesmo tempo e a porta trancada. De 1 a 4 pessoas.': "Boolla mootii qocaa waliin keessa darbaa: kutaalee bineensotaan guutaman, saanduqa kaarotii deemee deebi’u qabu, qabduu yeroo tokkotti nama lama barbaadan fi balbala cufame. Nama 1 hanga 4.",
  // O Ringue da Toca (16/11/2026)
  'Ringue da Toca': "Dirree Boollaa",
  'Boxe de reflexo contra três adversários do computador. Leia o aviso de cada golpe, esquive ou defenda e bata na brecha. Bater quando a luva brilha enche a estrela do soco forte.': "Booksii deebii saffisaa morkattoota kompiitaraa sadii irratti. Mallattoo rukuttaa tokkoon tokkoo dubbisi, miliqi ykn ittisi, banaa sana keessatti rukuti. Yeroo gaantiin calaqqisu rukutuun urjii rukuttaa jabaa guuta.",
  'Esquivar': "Miliqi",
  'Abaixar e defender': "Gadi jedhii ittisi",
  'Socar': "Rukuti",
  'Soco forte': "Rukuttaa jabaa",
  'Aperte os socos para levantar!': "Ka'uuf qabduuwwan rukuttaa tuqi!",
  'Lutas vencidas: {n}': "Lola mo'atame: {n}",
  'Nocaute!': "Kuffisa!",
  // O Comando Cenoura (16/11/2026)
  'Comando Cenoura': "Komaandoo Kaarotii",
  'Correr e atirar com a turma: o lança-cenouras mira em oito direções, a granada abre caminho e quem solta os coelhinhos presos ganha reforço. O dragão espera no fim: de 1 a 4 pessoas.': "Garee wajjin fiigi dhukaasi: qawween kaarotii kallattii saddeetiin ni qindeessa, boombiin harkaa karaa bana, namni ilmaan hantuutaa qafasa keessa jiran bilisa baase humna dabalataa argata. Dhuma irratti draagoniin eegaa jira: nama 1 hanga 4.",
  'Andar e mirar': "Deemi fi qindeessi",
  'Granada': "Boombii harkaa",
  // A Rota Estelar (16/11/2026)
  'Rota Estelar': "Karaa Urjii",
  'Coelhos em naves pela superfície de um planeta e pelo espaço: atire, segure o tiro para travar a mira, gire para desviar dos tiros e escolha o caminho na bifurcação. A turma voa a mesma rota, e o chefe espera no fim.': "Hilleensonni doonii samii keessa lafa pilaaneetii tokkoo irraa fi samii keessa: dhoowwi, xiyyeeffannaa cufuuf dhukaasa qabadhu, rasaasa deebisuuf naannaw, fi qaxxaamura irratti karaa filadhu. Gareen karaa tokko irra barrisa, hogganaan immoo dhuma irratti eeggata.",
  'Pirueta': "Naannawuu",
  'Segure para travar a mira': "Cufuuf qabadhu",
  // O Pinball da Horta (16/11/2026)
  'Pinball da Horta': "Piinboolii Mukaa",
  'Uma mesa de pinball na horta: segure a mola, rebata nos repolhos e derrube as três cenouras para acender a toca do coelho, que solta mais uma bola. Três bolas, e sacudir demais trava a mesa.': "Minjaala piinboolii mukaa kuduraa keessatti: sprinigii qabadhu, kaabeejiirratti utaalchisi, akkasumas qaroota sadan kuffisiitii boolla hilleensaa ibsisi; innis kubbaa biraa tokko gadi lakkisa. Kubbaa sadii, sochoosuun baay’ee minjaala cufa.",
  'Palhetas': "Rukuttoota",
  'Mola': "Sprinigii",
  'Sacudir': "Sochoosi",
  'Bola salva!': "Kubbaan baraarame!",
  'Multibola!': "Kubbaa baay’ee!",
  'Mesa travada!': "Minjaalli cufame!",
  'Cuidado!': "Of eeggadhu!",
  'Recordes dos amigos': "Rikardiiwwan hiriyootaa",
