  'Planador da toca': 'Xiyyaara qilee',
  'Desafios de voo: asa-delta, mochila a jato e paraquedas. Passe pelos anéis e pouse no alvo, perto do centro e de leve.': 'Qormaata balalii: hang glider, korojoo jet fi paaraashuutii. Geengoolee keessa darbii fi kaayyoo irratti, giddugala bira fi suuta qubadhu.',
