  'Um RPG de turnos curto: cada um controla um herói da turma. Escolham juntos, combinem ataques e vençam o dragão do castelo.': "RPG gabaabaa marsaa: namni hundi gootota garee keessaa tokko to’ata. Waliin filadhaa, haleellaa walitti makaa, dragoonii masaraa mo’adhaa.",
  'Faísca': "Qaanqee",
  'Erva': "Margaa",
  'Flecha': "Xiyya",
  'Aguenta mais e protege a turma.': "Caalaatti obsa, gareen eega.",
  'Acerta todos os inimigos.': "Diina hunda rukuta.",
  'Cura a turma e levanta quem caiu.': "Garee fayyisa, warra kufan ka’a.",
  'Um tiro forte, que passa da defesa.': "Dhukaasa cimaa ittisa keessa darbu.",
