  'Bichos da Toca': "Bineensota Boollaa",
  'Ande pelo campo, faça amizade com os bichos do mato usando uma cenoura e monte uma equipe de até seis. Vença o desafio da casa azul e, na sala, lute com a equipe de um amigo.': "Dirree keessa naannaʼi, bineensota marga dheeraa waliin kaarootiidhaan hiriyyoomi, garee hanga jahaa ijaari. Qormaata mana cuquliisaa moʼadhu, kutaa keessattis garee hiriyyaa waliin lolaa.",
