  "{nome} tem a palavra. Ouçam a defesa.": "{nome} jecha qaba. Ittisa dhaga'aa.",
  "{nome} terminou uma Maravilha: derrube-a em 2 minutos!": "{nome} Dinqii xumure: daqiiqaa 2 keessatti diigi!",
  "{nome} tirou dados iguais e joga de novo.": "{nome} lakkoofsa walfakkaataa darbatee irra deebi'ee taphata.",
  "{nome} usou: {item}.": "{nome} itti fayyadame: {item}.",
  "{nome} vai escolher quem enfrentar.": "{nome} eenyuun akka morku ni filata.",
  "{nome}: {tiros} tiros, {pct}% de acerto": "{nome}: dhukaasa {tiros}, {pct}% rukute",
  "1 contra 3": "1 kan 3",
  "2 contra 2": "2 kan 2",
  "A armadilha de {nome} disparou: quem sai junto?": "Kiyyoon {nome} hojjete: eenyutu waliin ba'a?",
  "A largada precisa de uma reta.": "Jalqabni karaa qajeelaa barbaada.",
  "A Maravilha de {nome} ficou de pé por 2 minutos.": "Dinqiin {nome} daqiiqaa 2 dhaabatee ture.",
  "A mesma posição pela terceira vez empata, e 20 lances só de dama sem comer também.": "Haalli tokkichi yeroo sadaffaaf yoo deebi'e walqixa; tarkaanfiin mootii qofaa 20 nyaata malee illee walqixa.",
  "À noite, veja quem os lobisomens atacaram. Uma poção salva essa pessoa e outra tira alguém do jogo; cada uma vale uma vez.": "Halkan, jeedalli namaa eenyuun akka haleelan ilaali. Qorichi tokko nama sana fayyisa, inni biraa nama tokko tapha keessaa baasa; tokkoon tokkoon isaanii al tokko qofa.",
  "A partida se desencontrou entre os computadores e foi encerrada.": "Taphichi kompiitarootaa gidduutti wal dhabee xumurame.",
  "A pedra que termina o lance na última fileira vira dama, que anda a diagonal inteira.": "Dhagaan tarkaanfii isaa sarara dhumaa irratti xumuru mootii ta'ee, diagonaala guutuu deema.",
  "A pista ainda não fecha a volta.": "Karaan ammallee marsaa hin cufne.",
  "A pista está curta demais.": "Karaan baay'ee gabaabaa dha.",
  "A pista passa por cima dela mesma.": "Karaan ofii isaa irra darba.",
  "A pista precisa de mais peças.": "Karaan qaamolee dabalataa barbaada.",
  "A turma age antes nas duas rodadas seguintes.": "Gareen marsaa itti aanan lamaan keessatti dursee socho'a.",
  "A turma está decidindo.": "Gareen murteessaa jira.",
  "A turma inteira leva bem menos dano nesta rodada.": "Marsaa kana gareen guutuun miidhaa baay'ee xiqqaa argata.",
  "A turma recupera vida no fim de três rodadas.": "Gareen dhuma marsaa sadii irratti lubbuu deebifata.",
