  "Mineiro": "Mineiro",
  "Mutirão na vizinhança, mas sem onde construir: receba {valor}.": "Hojii waloo ollaa, garuu bakki ijaaran hin jiru: {valor} fudhadhu.",
  "Mutirão na vizinhança: um prédio grátis em {cidade}.": "Hojii waloo ollaa: gamoo tokko bilisaan {cidade} keessatti.",
  "Na variante sem comer para trás, a pedra só come para a frente; a dama continua comendo para todo lado.": "Gosa duubatti hin nyaanne keessatti, dhagaan fuuldura qofa nyaata; mootichi garuu kallattii hundaan nyaachuu itti fufa.",
  "Não aprender": "Hin baratin",
  "Não atire na joaninha: ela é amiga da horta.": "Ilbiisa diimaa hin dhukaasin: hiriyaa oomishaa ti.",
  "No meio": "Gidduu",
  "No mineiro não há vira: as manilhas são o 4 de paus, o 7 de copas, o ás de espadas e o 7 de ouros.": "Mineiro keessa vira hin jiru: manilhaawwan 4 kilaabii, 7 onnee, aasii ispeedii fi 7 daaymandii dha.",
  "No mineiro, a mão vale 2, e o truco, o seis, o nove e o doze valem 4, 8, 10 e 12. Com 10 pontos, é a mão de dez: jogar valendo 4, ou correr e dar 2.": "Mineiro keessatti harki 2 gatii qaba, truco, ja'a, sagal fi kudha lama immoo 4, 8, 10 fi 12. Qabxii 10 yoo qabaatte, harka kudhan: gatii 4n taphadhu, ykn baqadhuu 2 kenni.",
  "Noite no Lobisomem: os microfones voltam no amanhecer.": "Halkan Nama-jeedala keessatti: maaykiraafoonni barii deebi'u.",
  "Noite: microfones desligados": "Halkan: maaykiraafoonni dhaamsamaniiru",
