  "No dominó de pontos, quem deixa as pontas somando 5, 10, 15… marca a soma na hora; a carroça na ponta conta as duas metades. A partida vai a 150.": "Dominoo qabxii keessatti, namni fiixeewwan ida’ama 5, 10, 15… godhu ida’ama sana yeroodhaan galmeessa; dhagaan dachaa fiixee irra jiru walakkaa lamaan isaa lakkaaʼa. Taphni hanga 150tti deema.",
  "No fim, as setas embaixo do tabuleiro andam pela partida, lance a lance.": "Dhuma irratti, xiyyaan gabatee jalaa taphicha keessa tarkaanfii tarkaanfiin deemu.",
