  "No tabuleiro de 10 × 10, as internacionais, são 20 pedras de cada lado; a regra é a mesma.": "Gabatee 10 × 10 irratti, kan idil-addunyaa, gama tokkoon tokkoon dhagaa 20 jira; seerri tokkuma.",
