  "Qual é o maior deserto quente do mundo?": "Gammoojjiin ho’aa addunyaa keessaa caalaa guddaa kami?",
  "Qual é o maior país do mundo em área?": "Biyyi bal’inaan addunyaa keessaa caalaa guddaa kami?",
  "Qual é o maior planeta do Sistema Solar?": "Pilaaneetiin Sirna Aduu keessaa caalaa guddaa kami?",
  "Qual é o mês mais curto do ano?": "Jiʼi waggaa keessaa caalaa gabaabaa kami?",
