  "Qual é o rio com mais água do mundo?": "Lagni addunyaa keessaa bishaan caalaa qabu kami?",
  "Qual órgão bombeia o sangue pelo corpo?": "Qaamni dhiiga qaama keessa facaasu kami?",
  "Qual planeta é conhecido como o planeta vermelho?": "Pilaaneetiin pilaaneetii diimaa jedhamee beekamu kami?",
