  "Qual sólido tem seis faces quadradas?": "Qaamni cimaan fuula rog-afurii jaʼa qabu kami?",
  "Quantas asas tem uma borboleta?": "Biraabiraan baallee meeqa qabdi?",
  "Quantas cores tem o arco-íris, na conta mais comum?": "Sabbanni waaqaa, akka lakkaaʼa baramaatti, halluu meeqa qaba?",
