  "Saara": "Saaharaa",
  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "Bineensi dhoksaa tokko baʼa, tokkoon tokkoon nama kaan tilmaama. Tilmaamni hundi waan dhoksaa sana wajjin walsimu agarsiisa: kutaa, nyaata, iddoo jiraatu fi ulfaatina. Namni tilmaama xiqqaadhaan argate qabxii caalaa argata.",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "Daayinoosaarri dhoksaa tokko baʼa, tokkoon tokkoon kaan tilmaama. Tilmaamni hundi waan dhoksaa sana wajjin walsimu agarsiisa: yeroo, nyaata, garee, dheerina fi iddoo itti argame. Namni tilmaama xiqqaadhaan argate qabxii caalaa argata.",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "Elementiin keemikaalaa dhoksaa tokko baʼa, tokkoon tokkoon kaan tilmaama. Tilmaamni hundi waan dhoksaa sana wajjin walsimu agarsiisa: maatii, haala qaamaa, yeroo, garee fi lakkoofsa atomii. Namni tilmaama xiqqaadhaan argate qabxii caalaa argata.",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "Naannoon Biraazil dhoksaa tokko baʼa, tokkoon tokkoon kaan tilmaama. Tilmaamni hundi fageenyaa fi kallattii gara dhoksaa sanaatti, naannoo, baay’ina uummataa, bal’ina, qarqara galaanaa fi daangaa biyya biraa wajjin agarsiisa. Namni tilmaama xiqqaadhaan argate qabxii caalaa argata.",
